cssStarter:
:root{--accent:#ff5e15;--ink:#171717;--dark:#171717;--dark-2:#212121;--body:#575f66;--surface:#ffffff;--surface-alt:#f5f6f8;--container:1280px;--gutter:32px;--section-y:105px}
body{font-family:'Archivo',sans-serif;font-size:16px;line-height:1.75;color:var(--body)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0 90px}
h1,h2,h3,h4,.btn,nav a{font-family:'Yantramanav',sans-serif}
.eyebrow{display:flex;align-items:center;gap:10px;font-family:'Yantramanav',sans-serif;font-size:18px;font-weight:500;line-height:1.1;text-transform:uppercase;color:var(--accent);margin-bottom:7px}
.eyebrow::before{content:'';width:35px;height:2px;background:var(--accent)}
.hero-title{font-size:60px;font-weight:700;line-height:1.13;text-transform:uppercase;color:#fff}
h2{font-size:48px;font-weight:700;line-height:1.1;color:var(--ink);margin:0 0 20px}
.on-dark h2{color:#fff}
h3{font-size:22px;font-weight:700;line-height:1.27;color:var(--ink)}
p{font-weight:300;line-height:1.63}
.btn{display:inline-flex;align-items:center;gap:12px;padding:15px 33px;border-radius:0;font-size:17px;font-weight:500;background:var(--accent);color:#fff}
.btn-dark{background:var(--dark)}
.card{background:#fff;padding:36px 40px;border-bottom:4px solid var(--accent)}
.num-chip{display:grid;place-items:center;width:50px;height:50px;background:var(--accent);color:#fff;font-family:'Yantramanav',sans-serif;font-size:20px;font-weight:700}
@media(max-width:768px){:root{--section-y:70px}.hero-title{font-size:38px}h2{font-size:32px}}
